com.mirth.connect.plugins.javascriptstep.script:
// Helper: Format HL7 YYYYMMDD to FHIR YYYY-MM-DD
function formatFhirDate(hl7Date) {
    if (!hl7Date || hl7Date.length < 8) return undefined;
    return hl7Date.substring(0, 4) + '-' + hl7Date.substring(4, 6) + '-' + hl7Date.substring(6, 8);
}

// Helper: Generate RFC4122-compliant UUID for transaction bundle references
function generateUUID() {
    return java.util.UUID.randomUUID().toString();
}




var mrn = msg['PID']['PID.3']['PID.3.1'].toString();
var lastName = msg['PID']['PID.5']['PID.5.1'].toString();
var firstName = msg['PID']['PID.5']['PID.5.2'].toString();
var dob = formatFhirDate(msg['PID']['PID.7']['PID.7.1'].toString());
var genderCode = msg['PID']['PID.8']['PID.8.1'].toString();
var gender = (genderCode === 'M') ? 'male' : (genderCode === 'F') ? 'female' : 'unknown';

var docNpi = msg['PV1']['PV1.7']['PV1.7.1'].toString();
var docLast = msg['PV1']['PV1.7']['PV1.7.2'].toString();
var docFirst = msg['PV1']['PV1.7']['PV1.7.3'].toString();

var payerId = msg['IN1']['IN1.3']['IN1.3.1'].toString();
var payerName = msg['IN1']['IN1.4']['IN1.4.1'].toString();
var subscriberId = msg['IN1']['IN1.36']['IN1.36.1'].toString();

var placerOrderNum = msg['ORC']['ORC.2']['ORC.2.1'].toString();
var cptCode = msg['OBR']['OBR.4']['OBR.4.1'].toString();
var cptText = msg['OBR']['OBR.4']['OBR.4.2'].toString();

var icdCode = msg['DG1']['DG1.3']['DG1.3.1'].toString();
var icdText = msg['DG1']['DG1.3']['DG1.3.2'].toString();

var patientUuid = 'urn:uuid:' + generateUUID();
var practitionerUuid = 'urn:uuid:' + generateUUID();
var coverageUuid = 'urn:uuid:' + generateUUID();
var conditionUuid = 'urn:uuid:' + generateUUID();
var serviceReqUuid = 'urn:uuid:' + generateUUID();

var patientResource = {
    resourceType: 'Patient',
    meta: { profile: ['http://hl7.org/fhir/us/core/StructureDefinition/us-core-patient'] },
    identifier: [{ system: 'http://cityhospital.org/mrn', value: mrn }],
    name: [{ use: 'official', family: lastName, given: [firstName] }],
    gender: gender,
    birthDate: dob
};
var practitionerResource = {
    resourceType: 'Practitioner',
    meta: { profile: ['http://hl7.org/fhir/us/core/StructureDefinition/us-core-practitioner'] },
    identifier: [{ system: 'http://hl7.org/fhir/sid/us-npi', value: docNpi }],
    name: [{ family: docLast, given: [docFirst], prefix: ['Dr.'] }]
};
var coverageResource = {
    resourceType: 'Coverage',
    meta: { profile: ['http://hl7.org/fhir/us/davinci-hrex/StructureDefinition/hrex-coverage'] },
    status: 'active',
    subscriberId: subscriberId,
    beneficiary: { reference: patientUuid },
    payor: [{ identifier: { system: 'http://payerhub.org/payer-id', value: payerId }, display: payerName }]
};
var conditionResource = {
    resourceType: 'Condition',
    meta: { profile: ['http://hl7.org/fhir/us/core/StructureDefinition/us-core-condition'] },
    clinicalStatus: {
        coding: [{ system: 'http://terminology.hl7.org/CodeSystem/condition-clinical', code: 'active' }]
    },
    verificationStatus: {
        coding: [{ system: 'http://terminology.hl7.org/CodeSystem/condition-ver-status', code: 'confirmed' }]
    },
    category: [{
        coding: [{ system: 'http://terminology.hl7.org/CodeSystem/condition-category', code: 'encounter-diagnosis' }]
    }],
    code: {
        coding: [{ system: 'http://hl7.org/fhir/sid/icd-10-cm', code: icdCode, display: icdText }],
        text: icdText
    },
    subject: { reference: patientUuid }
};
var serviceRequestResource = {
    resourceType: 'ServiceRequest',
    meta: { profile: ['http://hl7.org/fhir/us/core/StructureDefinition/us-core-servicerequest'] },
    identifier: [{ system: 'http://cityhospital.org/orders', value: placerOrderNum }],
    status: 'active',
    intent: 'order',
    category: [{
        coding: [{ system: 'http://snomed.info/sct', code: '363679005', display: 'Imaging' }]
    }],
    code: {
        coding: [{ system: 'http://www.ama-assn.org/go/cpt', code: cptCode, display: cptText }],
        text: cptText
    },
    subject: { reference: patientUuid },
    requester: { reference: practitionerUuid },
    reasonReference: [{ reference: conditionUuid }],
    insurance: [{ reference: coverageUuid }]
};

var transactionBundle = {
    resourceType: 'Bundle',
    type: 'transaction',
    entry: [
        {
            fullUrl: patientUuid,
            resource: patientResource,
            request: {
                method: 'POST',
                url: 'Patient',
                ifNoneExist: 'identifier=http://cityhospital.org/mrn|' + mrn
            }
        },
        {
            fullUrl: practitionerUuid,
            resource: practitionerResource,
            request: {
                method: 'POST',
                url: 'Practitioner',
                ifNoneExist: 'identifier=http://hl7.org/fhir/sid/us-npi|' + docNpi
            }
        },
        { fullUrl: coverageUuid, resource: coverageResource, request: { method: 'POST', url: 'Coverage' } },
        { fullUrl: conditionUuid, resource: conditionResource, request: { method: 'POST', url: 'Condition' } },
        { fullUrl: serviceReqUuid, resource: serviceRequestResource, request: { method: 'POST', url: 'ServiceRequest' } }
    ]
};

channelMap.put('fhirTransactionBundle', JSON.stringify(transactionBundle, null, 2));
channelMap.put('placerOrderNum', placerOrderNum);
channelMap.put('cptCode', cptCode);
channelMap.put('icdCode', icdCode); 

//tmp = JSON.parse(channelMap.get('fhirTransactionBundle')); 

// Assign a JSON STRING (not a parsed object) to tmp
tmp = channelMap.get('fhirTransactionBundle');

var rawResp = response.getMessage();

if (rawResp && rawResp.trim().startsWith('{')) {
    var resp = JSON.parse(rawResp);
    if (resp && resp.entry && resp.entry.length >= 5) {
        function extractRef(entry) {
            var loc = (entry.response && entry.response.location) ? entry.response.location : '';
            var parts = loc.split('/');
            return (parts.length >= 2) ? (parts[0] + '/' + parts[1]) : '';
        }

        channelMap.put('patientRef', extractRef(resp.entry[0]));
        channelMap.put('practitionerRef', extractRef(resp.entry[1]));
        channelMap.put('coverageRef', extractRef(resp.entry[2]));
        channelMap.put('conditionRef', extractRef(resp.entry[3]));
        channelMap.put('serviceRequestRef', extractRef(resp.entry[4]));
    }
} else {
    logger.error('HAPI FHIR returned non-JSON response: ' + rawResp);
}

channel.postprocessingScript:
