com.mirth.connect.plugins.javascriptstep.script:
var ctx = JSON.parse(connectorMessage.getRawData());

var patientId = ctx.patientRef.split('/')[1];
var srId = ctx.serviceRequestRef.split('/')[1];

var crdRequest = {
    hookInstance: java.util.UUID.randomUUID().toString(),
    fhirServer: "http://hapi.fhir.org/baseR4",
    hook: "order-sign",
    context: {
        userId: ctx.practitionerRef,
        patientId: patientId,
        draftOrders: {
            resourceType: "Bundle",
            type: "collection",
            entry: [
                {
                    resource: {
                        resourceType: "ServiceRequest",
                        id: srId,
                        status: "draft",
                        intent: "order",
                        code: {
                            coding: [{
                                system: "http://www.ama-assn.org/go/cpt",
                                code: ctx.cptCode
                            }]
                        },
                        subject: { reference: ctx.patientRef },
                        requester: { reference: ctx.practitionerRef },
                        reasonReference: [{ reference: ctx.conditionRef }],
                        insurance: [{ reference: ctx.coverageRef }]
                    }
                }
            ]
        }
    },
    prefetch: {
        patientToGreet: {
            resourceType: "Patient",
            id: patientId
        },
        clinicalDiagnosis: {
            resourceType: "Condition",
            code: {
                coding: [{
                    system: "http://hl7.org/fhir/sid/icd-10-cm",
                    code: ctx.icdCode
                }]
            }
        }
    }
};

var payloadStr = JSON.stringify(crdRequest, null, 2);
channelMap.put('crdPayload', payloadStr);
channelMap.put('handoffContext', JSON.stringify(ctx));
tmp = payloadStr;

var rawResp = response.getMessage();
var paNeeded = "no-auth";
if (rawResp && rawResp.trim().startsWith('{')) {
    var crdResp = JSON.parse(rawResp);
    if (crdResp && crdResp.systemActions && crdResp.systemActions.length > 0) {
        paNeeded = crdResp.systemActions[0].coverageInfo['pa-needed'];
    }
}
channelMap.put('paNeeded', paNeeded);

