com.mirth.connect.plugins.javascriptstep.script:
var ctx = JSON.parse(connectorMessage.getRawData());
var claimUuid = 'urn:uuid:' + java.util.UUID.randomUUID().toString();
var qrUuid = 'urn:uuid:' + java.util.UUID.randomUUID().toString();

// 1. Da Vinci DTR Completed QuestionnaireResponse (Auto-populated from EHR clinical chart)
var dtrQuestionnaireResponse = {
    resourceType: "QuestionnaireResponse",
    id: "dtr-qr-" + ctx.placerOrderNum,
    meta: {
        profile: ["http://hl7.org/fhir/us/davinci-dtr/StructureDefinition/dtr-questionnaireresponse"]
    },
    questionnaire: "http://localhost:8085/fhir/Questionnaire/lumbar-mri-pa",
    status: "completed",
    subject: { reference: ctx.patientRef },
    authored: new Date().toISOString(),
    author: { reference: ctx.practitionerRef },
    item: [
        {
            linkId: "1.1",
            text: "Has the patient completed at least 6 weeks of conservative physical therapy?",
            answer: [{ valueBoolean: true }]
        },
        {
            linkId: "1.2",
            text: "Duration of persistent low back pain (in weeks)",
            answer: [{ valueInteger: 8 }]
        },
        {
            linkId: "1.3",
            text: "Clinical rationale / red flag neurological symptoms",
            answer: [{ valueString: "8 weeks failed conservative PT; radiating L5 radiculopathy" }]
        }
    ]
};

// 2. Da Vinci PAS Claim referencing DTR QuestionnaireResponse via supportingInfo
var pasClaim = {
    resourceType: "Claim",
    id: "pas-req-" + ctx.placerOrderNum,
    meta: {
        profile: ["http://hl7.org/fhir/us/davinci-pas/StructureDefinition/profile-claim"]
    },
    identifier: [{
        system: "http://cityhospital.org/prior-auth-trace",
        value: ctx.placerOrderNum
    }],
    status: "active",
    type: {
        coding: [{
            system: "http://terminology.hl7.org/CodeSystem/claim-type",
            code: "professional"
        }]
    },
    use: "preauthorization",
    patient: { reference: ctx.patientRef },
    created: new Date().toISOString(),
    insurer: { display: "Aetna Health Plan" },
    provider: { reference: ctx.practitionerRef },
    priority: {
        coding: [{
            system: "http://terminology.hl7.org/CodeSystem/processpriority",
            code: "normal"
        }]
    },
    supportingInfo: [{
        sequence: 1,
        category: {
            coding: [{
                system: "http://hl7.org/fhir/us/davinci-pas/CodeSystem/PASSupportingInfoType",
                code: "patientEvent"
            }]
        },
        valueReference: { reference: qrUuid }
    }],
    diagnosis: [{
        sequence: 1,
        diagnosisCodeableConcept: {
            coding: [{
                system: "http://hl7.org/fhir/sid/icd-10-cm",
                code: ctx.icdCode
            }]
        }
    }],
    insurance: [{
        sequence: 1,
        focal: true,
        coverage: { reference: ctx.coverageRef }
    }],
    item: [{
        sequence: 1,
        productOrService: {
            coding: [{
                system: "http://www.ama-assn.org/go/cpt",
                code: ctx.cptCode
            }]
        },
        servicedDate: new Date().toISOString().substring(0, 10)
    }]
};

// 3. Da Vinci PAS Request Bundle (Claim MUST be entry[0], DTR QuestionnaireResponse in entry[1])
var pasRequestBundle = {
    resourceType: "Bundle",
    id: java.util.UUID.randomUUID().toString(),
    meta: {
        profile: ["http://hl7.org/fhir/us/davinci-pas/StructureDefinition/profile-pas-request-bundle"]
    },
    type: "collection",
    timestamp: new Date().toISOString(),
    entry: [
        { fullUrl: claimUuid, resource: pasClaim },
        { fullUrl: qrUuid, resource: dtrQuestionnaireResponse }
    ]
};

var pasStr = JSON.stringify(pasRequestBundle, null, 2);
channelMap.put('pasRequestBundle', pasStr);
channelMap.put('placerOrderNum', ctx.placerOrderNum);
channelMap.put('patientRef', ctx.patientRef);
channelMap.put('serviceRequestRef', ctx.serviceRequestRef);
channelMap.put('cptCode', ctx.cptCode);
channelMap.put('icdCode', ctx.icdCode);
tmp = pasStr;

var rawResp = response.getMessage();
if (rawResp && rawResp.trim().startsWith('{')) {
    var tokenJson = JSON.parse(rawResp);
    if (tokenJson.access_token) {
        channelMap.put('smartAccessToken', tokenJson.access_token);
        logger.info('=== SMART ON FHIR TOKEN ISSUED === Scope: ' + tokenJson.scope);
    }
} else {
    logger.error('Failed to obtain SMART OAuth token: ' + rawResp);
}

var rawResp = response.getMessage();
if (rawResp && rawResp.trim().startsWith('{')) {
    var pasResp = JSON.parse(rawResp);
    var claimResp = pasResp.entry[0].resource;
    var disposition = claimResp.disposition;
    var authNum = "PENDING";
    var exts = claimResp.item[0].extension;
    for (var i = 0; i < exts.length; i++) {
        if (exts[i].url.indexOf('extension-authorizationNumber') !== -1) {
            authNum = exts[i].valueString;
        }
    }
    logger.info('=== DA VINCI PAS RESULT === Disposition: ' + disposition + ' | Auth Number: ' + authNum);
} 

channelMap.put('pasDisposition', disposition);
channelMap.put('authNum', authNum);

properties.query:
var dbConn;
try {
    dbConn = DatabaseConnectionFactory.createDatabaseConnection(
        'com.microsoft.sqlserver.jdbc.SQLServerDriver',
        'jdbc:sqlserver://localhost:1433;databaseName=DaVinciPriorAuthDB',
        'sa',
        'YOUR_SQL_SERVER_PASSWORD'
    );

    var sql = "INSERT INTO PriorAuthAuditLog " +
              "(PlacerOrderNumber, PatientReference, ServiceRequestReference, CptCode, IcdCode, CrdDecision, PasDisposition, AuthorizationNumber) " +
              "VALUES (?, ?, ?, ?, ?, ?, ?, ?)";

    var params = new java.util.ArrayList();
    params.add($('placerOrderNum') || 'UNKNOWN');
    params.add($('patientRef') || 'UNKNOWN');
    params.add($('serviceRequestRef') || 'UNKNOWN');
    params.add($('cptCode') || 'UNKNOWN');
    params.add($('icdCode') || 'UNKNOWN');
    params.add('auth-needed');
    params.add($('pasDisposition') || 'PENDING');
    params.add($('authNum') || 'NONE');

    dbConn.executeUpdate(sql, params);
    logger.info('=== SQL SERVER AUDIT LOG SAVED === Order: ' + $('placerOrderNum') + ' | Auth: ' + $('authNum'));
} finally {
    if (dbConn) {
        dbConn.close();
    }
}

